protected getClientWindows(windowName?: string): TargetWindow[] {
        const frames = this.getFrameWindow().frames;
        if (windowName) {
            return [(frames as any)[windowName]];
        } else {
            const res: TargetWindow[] = [];
            for (let i = 0; i < frames.length; i++) {
                res.push(frames[i]);
            }
            return res;
        }
    }

